import type { StarlightRouteData } from "@astrojs/starlight/route-data";
import { defineRouteMiddleware } from "@astrojs/starlight/route-data";
import { SECTIONS, sectionForRoute } from "./sections";

type SidebarEntry = StarlightRouteData["sidebar"][number];

function flattenHrefs(entries: SidebarEntry[]): string[] {
	return entries.flatMap((entry) =>
		entry.type === "group" ? flattenHrefs(entry.entries) : [entry.href],
	);
}

// Scope the autogenerated sidebar to the current section: replace the full
// tree with the entries of the section's top-level group, keeping loose
// root-level entries (home, glossary) visible in every section. Starlight
// computes prev/next from the full sidebar before this middleware runs, so
// links crossing a section boundary are dropped here — unless the page set
// them explicitly via frontmatter.
export const onRequest = defineRouteMiddleware((context) => {
	const { starlightRoute } = context.locals;
	const section = sectionForRoute(starlightRoute.id);

	const sectionGroup = starlightRoute.sidebar.find(
		(entry) => entry.type === "group" && entry.label === section.id,
	);
	if (sectionGroup?.type !== "group") return;

	// The home link is filtered from display by SidebarList, so drop it from
	// the data too — otherwise prev/next pagination can point at it.
	const homeHref = `${import.meta.env.BASE_URL.replace(/\/+$/, "")}/`;
	const looseEntries = starlightRoute.sidebar.filter((entry) => {
		if (entry.type === "link") return entry.href !== homeHref;
		return !SECTIONS.some((candidate) => candidate.id === entry.label);
	});
	starlightRoute.sidebar = [...sectionGroup.entries, ...looseEntries];

	const visibleHrefs = new Set(flattenHrefs(starlightRoute.sidebar));
	const { pagination, entry } = starlightRoute;
	if (
		pagination.prev &&
		typeof entry.data.prev !== "object" &&
		!visibleHrefs.has(pagination.prev.href)
	) {
		pagination.prev = undefined;
	}
	if (
		pagination.next &&
		typeof entry.data.next !== "object" &&
		!visibleHrefs.has(pagination.next.href)
	) {
		pagination.next = undefined;
	}
});
